/// <reference lib="dom" />
// AgentSys client plugin SDK — public TypeScript declarations (API version 2).
//
// TypeScript is optional. A plugin is ordinary JavaScript: `exports.activate = api => { ... }` runs in the
// sandboxed host. These declarations exist for editors and for projects that choose TypeScript; there is no build
// step and no runtime package to import. See docs/plugin-sdk.md.
//
// The API an installed plugin receives is `AgentSysPluginApi`. The host injects it; a plugin never imports the
// application's internal modules.

export type Capability =
  | 'graph.read'
  | 'graph.write'
  | 'library.read'
  | 'library.write'
  | 'collections.read'
  | 'collections.write'
  | 'run.read'
  | 'run.start'
  | 'notifications.read'
  | 'notifications.write'
  | 'settings.read'
  | 'settings.write'
  | `secrets.use:${string}`
  | `net.fetch:${string}`;

export interface SemverRange {
  [pluginId: string]: string;
}

export interface PluginManifest {
  /** Stable id: letters, digits, ".", "_" or "-", at most 80 characters. */
  id: string;
  name: string;
  /** Semantic version, such as "1.2.0". */
  version: string;
  description?: string;
  /** A built-in icon name, such as "sparkles", "database" or "plug". */
  icon?: string;
  /** 1 (legacy) or 2 (current). A format 2 package uses 2. */
  api?: 1 | 2;
  /** AgentSys version range, for example {agentsys: ">=0.3.0 <1.0.0"}. */
  engines?: {agentsys?: string};
  capabilities?: Capability[];
  /** Other client plugins this plugin needs. Ranges use semver: ^1.2.0, ~1.2.0, >=1.0.0 <2.0.0. */
  dependencies?: SemverRange;
  author?: string;
  license?: string;
  homepage?: string;
}

export interface CollectionContribution {
  name: string;
  title?: string;
  description?: string;
  /** JSON-schema-like shape validated by the server: type, properties, required, enum, items, maxLength. */
  schema?: Record<string, unknown>;
  /** "create" (default) leaves an existing definition alone; "update" changes it and keeps every record. */
  strategy?: 'create' | 'update';
}

export interface LibraryNodeContribution {
  name: string;
  /** The JavaScript of one Script node. It runs on the server after deployment, without this plugin. */
  code: string;
  description?: string;
  folder?: string;
  icon?: string;
  inputs?: Array<string | Record<string, unknown>>;
  outputs?: Array<string | Record<string, unknown>>;
  grants?: Capability[];
  /** Adopt an existing node of the same name only when the package asks explicitly. */
  adopt?: boolean;
}

export interface WorkflowTemplateContribution {
  name: string;
  project?: string;
  /** Nodes to place. A native Event trigger is added by default so the saved workflow can run. */
  nodes?: Array<{library: string; point?: {x: number; y: number}}>;
  run?: boolean;
}

export interface PluginContributions {
  collections?: CollectionContribution[];
  library?: LibraryNodeContribution[];
  workflows?: WorkflowTemplateContribution[];
}

export interface PluginPackage {
  format: 2;
  manifest: PluginManifest;
  main?: string;
  /** Path -> text. Only relative .js and .json paths; modules use require('./relative') inside the package. */
  files?: Record<string, string>;
  /** PNG/JPEG/GIF/WebP base64 data URIs, or {type, data}. Available as api.asset(name). */
  assets?: Record<string, string | {type: string; data: string}>;
  contributes?: PluginContributions;
  /** Generated by tools/plugin-pack.js; a change is visible without being a security signature. */
  checksum?: string;
}

/** A legacy (format 1) package is still accepted. */
export interface LegacyPluginPackage {
  id: string;
  title: string;
  version?: string;
  description?: string;
  icon?: string;
  api?: 1 | 2;
  capabilities?: Capability[];
  source: string;
}

export type AnyPluginPackage = PluginPackage | LegacyPluginPackage;

export interface LifecycleContext {
  /** "install" the first time this version activates, "update" after a version change, "activate" otherwise. */
  hook: 'install' | 'update' | 'activate';
  from: string | null;
  to: string;
  /** The value returned by onUpdate/migrate last time; 0 for a new plugin. */
  dataVersion: number;
}

export interface PluginStorage {
  get<T = unknown>(key: string, fallback?: T): Promise<T | null>;
  set(key: string, value: unknown): Promise<true>;
  remove(key: string): Promise<true>;
}

export interface PluginSettings {
  get<T extends Record<string, unknown> = Record<string, unknown>>(): Promise<T>;
  set(value: Record<string, unknown>): Promise<true>;
}

export interface RequestOptions {
  /** The call is made with the short-lived token scoped to this plugin's capabilities. */
  method?: string;
  body?: unknown;
  query?: Record<string, string | number | boolean | undefined>;
}

export interface EnvironmentInfo {
  id: string;
  name: string;
  url: string;
  status: string;
  protocol?: number;
}

export interface CommandMeta {
  title?: string;
  icon?: string;
  order?: number;
}

export interface PageSpec {
  id: string;
  title?: string;
  description?: string;
  icon?: string;
  order?: number;
  /** false keeps the page out of the sidebar. */
  nav?: boolean;
  /** Return passive HTML (or an element); the host sanitizes it and uses the application's styles. */
  render(context: Record<string, unknown>): string | Node | Promise<string | Node>;
}

export interface SidebarItemSpec {
  id: string;
  title: string;
  icon?: string;
  order?: number;
  /** A path of this client, starting with "/". */
  href?: string;
  page?: string;
}

export interface ToolbarButtonSpec {
  id: string;
  command: string;
  title?: string;
  icon?: string;
  order?: number;
}

export interface MenuItemSpec {
  label: string;
  command: string;
  icon?: string;
  order?: number;
}

export interface HomeCardSpec {
  id: string;
  title?: string;
  icon?: string;
  order?: number;
  render(): string | Node | Promise<string | Node>;
}

export interface SettingsSectionSpec {
  id: string;
  title?: string;
  description?: string;
  order?: number;
  render(): string | Node | Promise<string | Node>;
}

export interface LibrarySectionSpec {
  id: string;
  title: string;
  description?: string;
  icon?: string;
  order?: number;
  nav?: boolean;
  render(): string | Node | Promise<string | Node>;
}

export interface InspectorSectionSpec {
  id: string;
  title?: string;
  description?: string;
  order?: number;
  /** "any" (default), "node" or "complex". */
  when?: 'any' | 'node' | 'complex';
  render(context: {
    node?: Record<string, unknown> | null;
    selection?: string[];
    project?: string;
    workflow?: string;
  }): string | Node | Promise<string | Node>;
}

export interface ResourceViewSpec {
  id: string;
  title?: string;
  description?: string;
  collection: string;
  icon?: string;
  order?: number;
  /** true adds a sidebar item for the view. */
  sidebar?: boolean;
  render(context: {
    collection: string;
    records: Array<{id: string; data: Record<string, unknown>; version: number; created: number; updated: number}>;
    total: number;
    page: Record<string, unknown>;
  }): string | Node | Promise<string | Node>;
}

export interface DialogAction {
  id?: string;
  label: string;
  /** A command of this plugin. Its first argument is the dialog's form values. */
  command?: string;
  args?: unknown[];
  variant?: 'primary' | 'secondary' | 'danger';
}

export interface DialogSpec {
  title?: string;
  /** Passive HTML; a form input is read as values for the action's command. */
  body?: string;
  html?: string;
  actions?: DialogAction[];
  /** false keeps the dialog open after an action; the default closes it. */
  close?: boolean;
}

export interface DialogAnswer {
  action: string | null;
  values?: Record<string, string>;
  result?: unknown;
  error?: string;
}

export interface PluginUiApi {
  /** A page at /ext/<plugin>/<id>. */
  addPage(spec: PageSpec): Promise<true>;
  addSidebarItem(spec: SidebarItemSpec): Promise<true>;
  addToolbarButton(spec: ToolbarButtonSpec): Promise<true>;
  /** Named menus: canvas:add, canvas:selection, library:resource, folder:<path>, nodes:, resource:<id>, section:<name>, plugin:<id>. */
  addMenuItem(menu: string, item: MenuItemSpec): Promise<true>;
  /** The same registry as addMenuItem('canvas:selection'). */
  addContextMenu(item: MenuItemSpec): Promise<true>;
  addHomeCard(spec: HomeCardSpec): Promise<true>;
  addSettingsSection(spec: SettingsSectionSpec): Promise<true>;
  addLibrarySection(spec: LibrarySectionSpec): Promise<true>;
  addInspectorSection(spec: InspectorSectionSpec): Promise<true>;
  addResourceView(spec: ResourceViewSpec): Promise<true>;
  showDialog(spec: DialogSpec): Promise<DialogAnswer>;
  closeDialog(): Promise<true>;
  /** Scoped CSS; @import and url(...) are refused. */
  addStyles(css: string): Promise<true>;
  notify(notification: {
    title: string;
    body?: string;
    level?: 'info' | 'success' | 'warning' | 'error';
    source?: string;
  }): Promise<unknown>;
  toast(message: string, bad?: boolean): Promise<true>;
  navigate(path: string): Promise<true>;
  refresh(): Promise<true>;
  escape(value: unknown): string;
  pageHref(pageId: string): string;
}

export interface PluginCommandsApi {
  register(id: string, handler: (...args: unknown[]) => unknown, meta?: CommandMeta): Promise<true>;
  /** Only this plugin's own commands; a foreign id is refused. */
  execute(id: string, ...args: unknown[]): Promise<unknown>;
}

export interface PluginLibraryApi {
  list(): Promise<Array<Record<string, unknown>>>;
  get(id: string): Promise<Record<string, unknown>>;
  /** Creates a Script-backed Library node owned by this plugin; the server runs it without the plugin. */
  createNode(spec: LibraryNodeContribution): Promise<{id: string; name: string}>;
  /** Returns a node with the same name, or creates one. */
  ensureNode(spec: LibraryNodeContribution): Promise<{id: string; name: string}>;
  /** Replaces a node this plugin owns; a person's node is refused by the server. */
  updateNode(id: string, spec: LibraryNodeContribution): Promise<{id: string; name: string}>;
  deleteNode(id: string): Promise<unknown>;
}

export interface CollectionRecord<T = Record<string, unknown>> {
  id: string;
  data: T;
  version: number;
  created: number;
  updated: number;
}

export interface PluginCollectionsApi {
  list(): Promise<Array<{name: string; title: string; description: string; schema: Record<string, unknown>}>>;
  define(name: string, definition: {title?: string; description?: string; schema?: Record<string, unknown>}): Promise<unknown>;
  records<T = Record<string, unknown>>(
    name: string,
    query?: {offset?: number; limit?: number; q?: string}
  ): Promise<{total: number; records: Array<CollectionRecord<T>>; next_offset: number | null}>;
  create<T = Record<string, unknown>>(name: string, data: T, id?: string): Promise<CollectionRecord<T>>;
  update<T = Record<string, unknown>>(
    name: string,
    id: string,
    data: T,
    /** The version read with the record; a stale version is 409 conflict. */
    version?: number
  ): Promise<CollectionRecord<T>>;
  remove(name: string, id: string): Promise<unknown>;
}

export interface PluginWorkflowsApi {
  projects(): Promise<Array<{id: string; name: string; description: string; workflow_count: number}>>;
  createProject(name: string): Promise<{id: string; name: string}>;
  workflows(projectId: string): Promise<{project: Record<string, unknown>; workflows: Array<Record<string, unknown>>}>;
  createWorkflow(projectId: string, name: string): Promise<{id: string}>;
  /** Places a Library node on a canvas; the returned ids are ordinary graph ids. */
  placeNode(
    projectId: string,
    workflowId: string,
    resourceId: string,
    point?: {x: number; y: number}
  ): Promise<Record<string, unknown>>;
}

export interface AgentSysPluginApi {
  readonly id: string;
  readonly title: string;
  readonly description: string;
  readonly icon: string;
  readonly version: string;
  readonly api: number;
  readonly capabilities: Capability[];
  readonly manifest: Pick<PluginManifest, 'id' | 'name' | 'version' | 'api' | 'capabilities' | 'icon'>;
  /** Aborted when the plugin is stopped; long-running work should observe it. */
  readonly signal: AbortSignal;
  /** A bundled image as a data URI, or "" when the package has no such asset. */
  asset(name: string): string;
  assets(): Record<string, string>;
  log(...args: unknown[]): void;
  /** Calls the active server through the host transport; capabilities are checked before it leaves the page. */
  request(method: string, path: string, body?: unknown, query?: Record<string, string | number | boolean | undefined>): Promise<any>;
  storage: PluginStorage;
  settings: PluginSettings;
  commands: PluginCommandsApi;
  ui: PluginUiApi;
  library: PluginLibraryApi;
  collections: PluginCollectionsApi;
  workflows: PluginWorkflowsApi;
  net: {
    /** POST /api/net; the server applies its egress allowlist and substitutes {{secret:name}} placeholders. */
    fetch(spec: {url: string; method?: string; headers?: Record<string, string>; body?: string; timeout?: number}): Promise<{status: number; text: string}>;
  };
  secrets: {
    /** Metadata only; a client plugin never receives a secret value. */
    present(name: string): Promise<{name: string; present: boolean}>;
  };
  env: {info(): Promise<EnvironmentInfo>};
  onDidChange(listener: (keys: string[]) => void): () => boolean;
  on(event: 'change', listener: (keys: string[]) => void): () => boolean;
}

export type Deactivate = (api: AgentSysPluginApi) => void | Promise<void>;

/** The module a package's main file exports. Plain JavaScript works without these types. */
export interface PluginModule {
  activate(api: AgentSysPluginApi): void | Deactivate | Promise<void | Deactivate>;
  deactivate?(api: AgentSysPluginApi): void | Promise<void>;
  onInstall?(api: AgentSysPluginApi, context: LifecycleContext): unknown | Promise<unknown>;
  /** Return a new data version, or undefined to keep the old one. */
  onUpdate?(api: AgentSysPluginApi, context: LifecycleContext): number | void | Promise<number | void>;
  migrate?(api: AgentSysPluginApi, context: LifecycleContext): number | void | Promise<number | void>;
  onUninstall?(api: AgentSysPluginApi, context: {version: string}): void | Promise<void>;
}

declare global {
  /** Helper injected into a Script that runs on the server (not a client plugin). */
  function agentsys(method: string, path: string, body?: unknown): Promise<any>;
}
